 $('enAutoAnalysis').onchange=()=>{settings.autoAnalysis=$('enAutoAnalysis').checked;saveSettings()};
 function toggleAnalysis(){if(!$('enAnalysis').hidden){closeAnalysis(true);return}if(['dictation','puzzle'].includes(p.mode)&&!passed){helped=true;persist()}analysis()}
 for(const id of ['enReveal','enAnalysisClose'])$(id).onmousedown=e=>e.preventDefault();$('enAnalysisClose').onclick=()=>closeAnalysis(true);
 for(const [panel,toggle,close]of [['enDirectory','enDirectoryToggle','enDirectoryClose'],['enSound','enSoundToggle','enSoundClose']]){$(toggle).onclick=()=>{const open=$(panel).hidden;closePanels();$(panel).hidden=!open;$(toggle).setAttribute('aria-expanded',String(open))};$(close).onclick=()=>{closePanels();if(lastInput?.isConnected)lastInput.focus({preventScroll:true})}}
 document.addEventListener('keydown',e=>{if(!active||uiScreen!=='practice'||e.isComposing||e.defaultPrevented)return;if(e.key==='Escape'){closePanels();if(lastInput?.isConnected)lastInput.focus({preventScroll:true})}else if(e.key==='Enter'&&p.mode==='puzzle'&&!e.altKey&&!e.ctrlKey&&!e.metaKey&&!e.shiftKey&&!e.target.closest?.('input,textarea,select,#enAnalysis,#enSound,#enDirectory')){e.preventDefault();check()}else if(e.altKey&&e.code==='KeyP'){e.preventDefault();play()}else if(e.altKey&&e.code==='KeyA'){e.preventDefault();toggleAnalysis()}});
 $('enSearch').oninput=$('enDomain').onchange=$('enKindFilter').onchange=$('enLevelFilter').onchange=renderLibrary;$('enMode').onchange=()=>{save();p.mode=$('enMode').value;renderSentence()};$('enCheck').onclick=check;$('enRetry').onclick=()=>{delete modeResult().draft;renderSentence()};$('enReveal').onclick=toggleAnalysis;$('enPrev').onclick=()=>move(-1);$('enNext').onclick=()=>move(1);$('enPlay').onclick=play;$('enFavorite').onclick=()=>{result().favorite=!result().favorite;$('enFavorite').textContent=result().favorite?'★ 已收藏':'☆ 收藏';outline();save()};$('enFilter').onchange=outline;$('enTimer').onclick=()=>{paused=!paused;syncStudyTime()};$('enRecord').onclick=record;$('enSpoken').onclick=done;$('enNotes').oninput=()=>{result().notes=$('enNotes').value;save()};
 $('enVoicePreview').onclick=previewVoice;$('enVoice').onchange=()=>{settings.voice=$('enVoice').value;stopAudio();$('enVoiceStatus').textContent='';saveSettings();warm()};$('enRate').onchange=()=>{settings.rate=Number($('enRate').value);audio.playbackRate=settings.rate;saveSettings()};$('enPreload').onchange=()=>{settings.preload=$('enPreload').checked;saveSettings();warm()};$('enAllowCloud').onchange=()=>{if(collection?.kind==='builtin'){for(const id of collection.parts.keys())settings.online[id]=$('enAllowCloud').checked}else settings.online[origin().id]=$('enAllowCloud').checked;stopAudio();saveSettings();warm()};$('enRetryAudio').onclick=()=>cache.retry();$('enLoop').onchange=()=>{if(!$('enLoop').checked)clearTimeout(loopTimer)};
 $('enAI').onclick=()=>generate();$('enResumeAI').onclick=()=>generate(true);$('enStopAI').onclick=()=>stopAI();$('enParse').onclick=async()=>{try{const x=input();if(/^[{[]/.test(x.text.trim()))throw Error('课程 JSON 请在自建素材库的「导入题库」中读取');const c=C.parse(x.text,x.title,x.domain);c.source=x.source;c.level=x.level;aiJob=null;$('enResumeAI').hidden=true;$('enGenerationProgress').hidden=true;$('enFailedDraft').hidden=true;await preview(c);message('已分句，请核对中文和解析后保存。','success')}catch(e){message(e.message,'error')}};
 $('enValidate').onclick=async()=>{try{const c=C.clean(JSON.parse($('enDraftJson').value));let validated=c;if(materialSession)validated=await api.validateSession({session_id:materialSession,lesson:c,partial:draftPartial});if(aiJob&&JSON.stringify(input())===JSON.stringify(aiJob.input))aiJob.sentences=JSON.parse(JSON.stringify(validated.sentences));await preview(validated,materialSession,draftPartial);message('课程结构校验通过。','success')}catch(e){message(e.message,'error')}};
 $('enSave').onclick=async()=>{try{let c=C.clean(JSON.parse($('enDraftJson').value));if(materialSession)c=await api.validateSession({session_id:materialSession,lesson:c,partial:draftPartial});const saved=await api.save(c,true);settings.online[saved.id]=$('enCloud').checked;await saveSettings();await refresh();await load(saved.id);message(saved.existing?'相同课程已存在，继续使用原记录。':'题库已保存，旧课程与记录继续保留。','success')}catch(e){message(e.message,'error')}};
 $('enFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;$('enAI').disabled=$('enParse').disabled=$('enFile').disabled=true;$('enResumeAI').hidden=true;try{if(!/\.(pdf|txt|md)$/i.test(file.name))throw Error('这里支持 PDF、TXT、Markdown；课程 JSON 请使用自建素材库的「导入题库」');if(file.size>10*1024*1024)throw Error('文件最大 10 MB');message('正在本机读取素材…','loading');let value;if(/\.pdf$/i.test(file.name)){const pdf=await import('./english-pdf.mjs');value=await pdf.extractPDF(await file.arrayBuffer(),{onProgress:(page,total)=>message('正在本机读取 PDF：'+page+' / '+total+' 页…','loading')})}else value=await file.text();
 if(!$('enTitle').value.trim())$('enTitle').value=file.name.replace(/\.[^.]+$/,'').slice(0,160);uploadedSourceTitle=file.name;aiJob=null;$('enFailedDraft').hidden=true;$('enGenerationProgress').hidden=true;$('enMaterial').value=value;materialSession=null;$('enDraft').hidden=true;message('素材已载入。请核对正文顺序，删除页眉与参考文献，再选择 AI 整理或直接分句。','success');
 }catch(e){message(e.message,'error')}finally{$('enAI').disabled=$('enParse').disabled=$('enFile').disabled=false;e.target.value=''}};
 $('enExport').onclick=async()=>{try{if(lesson)await save();const saved=await api.list(),courses=[],progress={};for(const c of saved){courses.push(await api.get(c.id));progress[c.id]=await api.progress(c.id)}download('科研英语-题库备份.json',{format:'research-english-backup-v1',exportedAt:new Date().toISOString(),lessons:courses,progress});message('已导出题库与练习记录。录音请单独下载。','success')}catch(e){message(e.message,'error')}};
 $('enAgentToggle').onclick=()=>{const guide=$('enAgentGuide');guide.hidden=!guide.hidden;$('enAgentToggle').setAttribute('aria-expanded',String(!guide.hidden));if(!guide.hidden)guide.scrollIntoView?.({block:'nearest',behavior:'auto'})};$('enAgentClose').onclick=()=>{$('enAgentGuide').hidden=true;$('enAgentToggle').setAttribute('aria-expanded','false');$('enAgentToggle').focus({preventScroll:true})};
 $('enCopyMCP').onclick=()=>copyToClipboard(`请用科研小盒 MCP 为我创建一门科研英语课程。主题：${$('enTitle').value||$('enImportDomain').value}。题库名称必须保留为 ${$('enTitle').value||'我的科研素材'}。请先用你自己的网络工具抓取可合法访问的文章/视频文字，或读取我提供的 PDF，记录真实来源链接。调用 micro_tools_prepare_english_material，传 title=${$('enTitle').value||'我的科研素材'}、text 或本机 PDF 的 file_path、source、domain=${$('enImportDomain').value}、level=${$('enLevel').value}、count=${$('enCount').value}；source.kind=${$('enSourceKind').value}。遵循返回 schema 生成每句 8–16 词（最多 22 词）的双语短句、音标、语法解析、source_id 原文片段编号和科研追问；程序会回填 quote 原文依据，不调用插件模型 API。先调用 micro_tools_save_english_lesson(save:false) 校验预览；完成核对后 save:true 保存新课。已有题库不能覆盖。来源：${$('enSourceUrl').value||'请按主题查找'}。`,'已复制建库指令');
 $('enMaterial').addEventListener('input',()=>{uploadedSourceTitle=''});
 $('enCopyCoach').onclick=()=>copyToClipboard(`Act as my research English speaking coach. Ask one question at a time and wait for my answer. Current practice: ${sentence().en}\nStart with: ${sentence().question||'Explain your research project.'}\nMy notes: ${result().notes||'(not provided)'}\nCorrect two important language issues, then ask a research follow-up. Do not invent my results or contributions.`,'已复制口语提示');
 setInterval(()=>{const now=Date.now();syncStudyTime();if(recorder?.state==='recording'){if(now-recordingSince>300000)stopRecording();else $('enRecord').textContent='■ 停止录音 '+clock((now-recordingSince)/1000)}},1000);setInterval(()=>{if(active&&lesson&&uiScreen==='practice')save()},15000);
 document.addEventListener('visibilitychange',()=>{windowFocused=document.hasFocus();pointerInside=!document.hidden&&document.documentElement.matches(':hover');syncStudyTime();if(document.hidden){stopAudio();stopRecording();if(lesson)save()}});
 document.documentElement.addEventListener('mouseenter',()=>{pointerInside=true;syncStudyTime()});document.documentElement.addEventListener('mouseleave',()=>{pointerInside=false;syncStudyTime()});document.addEventListener('mousemove',()=>{if(!pointerInside){pointerInside=true;syncStudyTime()}},{passive:true});
 window.addEventListener('focus',()=>{windowFocused=true;pointerInside=document.documentElement.matches(':hover');syncStudyTime()});window.addEventListener('blur',()=>{windowFocused=false;pointerInside=false;syncStudyTime();if(lesson)save()});window.addEventListener('pagehide',()=>{if(lesson)save();stopRecording()});
 window.EnglishUI={back(){if(uiScreen==='hub')return false;showHub();return true},async onView(view){const entering=!active&&view==='english';active=view==='english';syncStudyTime();if(!active){stopAudio();stopRecording();closePanels();cache.enabled=false;$('settingsBtn')?.classList.remove('en-hidden-fab');if(lesson)save();return}try{await initialize();if(entering)await showHub();if(lesson&&uiScreen==='practice'){$('settingsBtn')?.classList.add('en-hidden-fab');warm()}}catch{}}};
